// uart - UART Controller IP (Third Party)
// Generated by soc-build skill

`timescale 1ns / 1ps

module uart (
    input  wire        clk,
    input  wire        rst_n,
    // APB interface
    input  wire        psel,
    input  wire        penable,
    input  wire        pwrite,
    input  wire [7:0]  paddr,
    input  wire [31:0] pwdata,
    output reg  [31:0] prdata,
    output reg         pready,
    // UART signals
    input  wire        uart_rx,
    output reg         uart_tx,
    output reg         tx_ready,
    output reg         rx_valid,
    output reg  [7:0]  rx_data,
    // Interrupt
    output reg         irq
);

    reg [7:0]  tx_data_reg;
    reg        tx_start_reg;
    reg [15:0] baud_div_reg;
    reg [2:0]  tx_bit_cnt;
    reg [11:0] tx_sample_cnt;
    reg [7:0]  rx_shift_reg;
    reg [11:0] rx_sample_cnt;
    reg [2:0]  rx_bit_cnt;
    reg        rx_busy;

    // Simple APB register interface
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_data_reg  <= 8'b0;
            tx_start_reg <= 1'b0;
            baud_div_reg <= 16'd651;  // 9600bps @ 1MHz
            prdata       <= 32'b0;
            pready       <= 1'b0;
        end else begin
            pready <= psel & penable;
            if (psel && penable && pwrite) begin
                case (paddr)
                    8'h00: tx_data_reg  <= pwdata[7:0];
                    8'h04: tx_start_reg <= pwdata[0];
                    8'h08: baud_div_reg <= pwdata[15:0];
                    default: ;
                endcase
            end else if (psel && penable && !pwrite) begin
                case (paddr)
                    8'h00: prdata <= {24'b0, tx_data_reg};
                    8'h04: prdata <= {31'b0, tx_ready};
                    8'h08: prdata <= {16'b0, baud_div_reg};
                    8'h0C: prdata <= {24'b0, rx_data};
                    8'h10: prdata <= {31'b0, rx_valid};
                    default: prdata <= 32'b0;
                endcase
            end
            if (tx_start_reg && !tx_ready) begin
                tx_start_reg <= 1'b0;
            end
        end
    end

    // TX logic (simplified)
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            uart_tx      <= 1'b1;
            tx_ready     <= 1'b1;
            tx_bit_cnt   <= 3'b0;
            tx_sample_cnt<= 12'b0;
        end else begin
            if (tx_start_reg && tx_ready) begin
                tx_ready <= 1'b0;
                tx_bit_cnt <= 3'b0;
                tx_sample_cnt <= 12'b0;
            end else if (!tx_ready) begin
                if (tx_sample_cnt == baud_div_reg[15:4]) begin
                    tx_sample_cnt <= 12'b0;
                    if (tx_bit_cnt == 3'd7) begin
                        tx_ready <= 1'b1;
                        uart_tx  <= 1'b1;
                    end else begin
                        tx_bit_cnt <= tx_bit_cnt + 1'b1;
                        uart_tx <= tx_data_reg[tx_bit_cnt];
                    end
                end else begin
                    tx_sample_cnt <= tx_sample_cnt + 1'b1;
                end
            end
        end
    end

    // RX logic (simplified)
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_valid     <= 1'b0;
            rx_data      <= 8'b0;
            rx_shift_reg <= 8'b0;
            rx_sample_cnt<= 12'b0;
            rx_bit_cnt   <= 3'b0;
            rx_busy      <= 1'b0;
            irq          <= 1'b0;
        end else begin
            rx_valid <= 1'b0;
            irq      <= rx_valid;  // pulse interrupt on rx valid
            if (!rx_busy && !uart_rx) begin
                rx_busy <= 1'b1;
                rx_sample_cnt <= 12'b0;
                rx_bit_cnt <= 3'b0;
            end else if (rx_busy) begin
                if (rx_sample_cnt == baud_div_reg[15:4]) begin
                    rx_sample_cnt <= 12'b0;
                    if (rx_bit_cnt == 3'd7) begin
                        rx_busy <= 1'b0;
                        rx_data <= rx_shift_reg;
                        rx_valid <= 1'b1;
                    end else begin
                        rx_shift_reg[rx_bit_cnt] <= uart_rx;
                        rx_bit_cnt <= rx_bit_cnt + 1'b1;
                    end
                end else begin
                    rx_sample_cnt <= rx_sample_cnt + 1'b1;
                end
            end
        end
    end

endmodule
